CREATE PROCEDURE sp_rpt_Toast_Item_to_Tag_map_for_Guest_Count_and_Consolidated_Categry AS /** ## Procedure Name       *[toast].[dbo].[sp_rpt_Toast_Item_to_Tag_map_for_Guest_Count_and_Consolidated_Categry]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20251017   **Report Name**         *Toast Item to Tag map for Guest Count and Consolidated Categry*   **Summary**   *summary of report*      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;  		declare @Params varchar(2000) = (select '' as Params for json path)      	create table #Results 		( 			Tab varchar(20), 			MultiLocationID varchar(20), 			Item_PLU int, 			Aloha_PLU int, 			ItemName varchar(100), 			IsInCat1089 varchar(3), 			AlohaGuestWeight float, 			PMixCategory varchar(50), 			GuestCountTag varchar(22) 		)  		insert into #Results (tab, MultiLocationID, Item_PLU, ItemName) 		select distinct 			case 				when i.Item_Name like '%(Entree)%' then 'Entree' 				when i.Item_Name like '%(Meal Deal%' then 'Meal Deal' 				when i.Item_Name like '%Pairing Choice)%' then 'Pairing choices' 				when i.Item_Name like '%(Pick 3 Entree)%' then 'Pick 3' 				when i.Item_Name like '%(Catering)' then 'Catering' 			end as Tab, 			MultiLocationID, 			Item_PLU, 			Item_Name 		from toast.dbo.cfg_menu_items i 		where i.Item_Name like '%(Entree)%' 		or i.Item_Name like '%Pairing Choice)%' 		or i.Item_Name like '%(Meal Deal%' 		or i.Item_Name like '%(Pick 3 Entree)%' 		or i.Item_Name like '%(Catering)'  		update #Results set 			Aloha_PLU = p.AlohaPLU 		from #Results r 		join toast.dbo.cfg_map_PLU_Toast_to_Aloha p 		on r.Item_PLU = p.ToastPLU  		update #Results set 			IsInCat1089 = 'Yes', 			AlohaGuestWeight = i.Guests 		from #Results r 		join dev_aloha.dbo.categoryitem ci 		on r.Aloha_PLU = ci.FKItemId 		join dev_aloha.dbo.item i 		on ci.FKItemId = i.ItemID 		where ci.CategoryItemId = 1089  		update #Results set 			IsInCat1089 = 'No' 		where IsInCat1089 = '' 		or IsInCat1089 is null  		update #Results set 			PMixCategory = t.Tag_Name 		from #Results r 		join toast.dbo.cfg_map_item_tags mit 		on r.MultiLocationID = mit.MultiLocationID 		join toast.dbo.cfg_tags t 		on mit.Tag_GUID = t.Tag_GUID 		where (t.Tag_Name like '* Consol%' 				or 			   t.tag_name like '%Cater%')  		update #Results set 			GuestCountTag = t.Tag_Name 		from #Results r 		join toast.dbo.cfg_map_item_tags mit 		on r.MultiLocationID = mit.MultiLocationId 		join toast.dbo.cfg_tags t 		on mit.Tag_GUID = t.Tag_GUID 		where t.Tag_Name like 'Guest%'  		select * 		from #Results 		order by Tab, Aloha_PLU, Item_PLU, MultiLocationID, ItemName  		drop table #Results                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END